const {vec} = NMath;
const {vertices} = await IO.loadMesh("/assets/bob.obj");

// ---------- parameters ----------
const K = 10;                 // number of clusters
const eigenK = 16;            // size of the spectral embedding
const knnNeighbors = 4;
const sigma = 0.005;
const kmeansIterations = 30;

// ---------- helpers ----------
const normalizeVectors = vectors => {
    const mean = vectors.reduce((sum, v) => sum.add(v), vec.zero(3)).scale(1 / vectors.length);
    const centered = vectors.map(v => v.sub(mean));
    const max = Math.max(...centered.map(v => Math.max(...v.toArray().map(Math.abs))));
    const scaled = max === 0 ? centered : centered.map(v => v.scale(1 / max));
    return scaled.map(({components: [x, y, z]}) => vec(z, x, y));
};

// Runs k-means for a fixed number of iterations and returns one cluster label per point.
const runKmeans = (data, k, iterations) => {
    const kmeans = new Kmeans(k, data[0].dim);
    for (let i = 0; i < iterations; i++) kmeans.update(data);
    return data.map(x => kmeans.predictIndex(x));
};

const randomColors = n => NArray.range(n).map(() => [Math.random(), Math.random(), Math.random()]).toArray();
const colorByLabel = (labels, palette) => labels.map(label => palette[label]);

// ---------- data ----------
const pts = normalizeVectors(vertices.map(v => vec(...v)));
const points = pts.map(p => p.toArray());

// ---------- spectral embedding ----------
const graph = Graph.knn(pts, knnNeighbors, (x, y) => x.sub(y).length());
const laplacian = graph.laplacian((i, j) => Math.exp(-i.vertex.sub(j.vertex).squareLength() / sigma));
const {eigenvectors} = laplacian.eigen({maxFirst: false, k: Math.min(eigenK, pts.length)});
// point i  ->  [eigenvector_0[i], ..., eigenvector_{eigenK-1}[i]]
const eigenArrays = eigenvectors.map(e => e.toArray());
const spectralCoords = pts.map((_, i) => vec(...eigenArrays.map(e => e[i])));

// ---------- clustering ----------
const palette = randomColors(K);
const simpleLabels = runKmeans(pts, K, kmeansIterations);
const spectralLabels = runKmeans(spectralCoords, K, kmeansIterations);

// ---------- plots ----------
const simpleKmeansPlot = IO.plotPointCloud(points, {color: colorByLabel(simpleLabels, palette)});
const spectralKmeansPlot = IO.plotPointCloud(points, {color: colorByLabel(spectralLabels, palette)});

const ui = IO.UI(
    {type: "group", value: () => [
        {type: "canvas", value: () => simpleKmeansPlot},
        {type: "canvas", value: () => spectralKmeansPlot},
    ]},
);
ui;
